<?php if($page==='dashboard'):?><div class="heading"><div><h1><?=e($me['role']==='platform_admin'?'Platform overview':'Welcome, '.explode(' ',$me['name'])[0])?></h1><div class="sub">A clear view of your school workspace.</div></div><?php if($me['role']!=='platform_admin'):?><a class="btn" href="?page=leaves#new">＋ New request</a><?php endif;?></div><?php if(in_array($me['role'],['employee','teacher','student'],true)):?><section class="grid" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr));margin:0 0 18px"><?php foreach(array_slice($balanceSummary,0,4) as $b):?><article class="card"><div class="muted"><?=e($b['category'])?></div><div class="num"><?=e(number_format($b['available'],1))?> days remaining</div><small>Pending <?=e(number_format($b['pending'],1))?> · projected <?=e(number_format($b['projected'],1))?></small></article><?php endforeach;?><a class="card" href="?page=balances"><b>Open full leave tracker →</b></a></section><?php endif;?><section class="grid"><?php $labels=$me['role']==='platform_admin'?['Schools'=>'total','Awaiting approval'=>'pending','Active'=>'approved']:['All requests'=>'total','Pending'=>'pending','Approved'=>'approved','Rejected'=>'rejected'];foreach($labels as $lab=>$key):?><article class="card"><div class="stat"><?=e($lab)?></div><div class="num"><?=e($stats[$key]??0)?></div></article><?php endforeach;?></section><section class="card section"><h2><?=e($me['role']==='platform_admin'?'Recent school registrations':'Recent leave requests')?></h2><div class="tablebox"><table><thead><tr><?php if($me['role']==='platform_admin'):?><th>School</th><th>Created</th><th>Status</th><?php else:?><th>Requester</th><th>Dates</th><th>Reason</th><th>Status</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if($me['role']==='platform_admin'):?><td><?=e($r['name'])?></td><td><?=e(substr($r['created_at'],0,10))?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><?php else:?><td><?=e($r['person'])?></td><td><?=e($r['start_date'])?> → <?=e($r['end_date'])?></td><td><?=e(mb_strimwidth($r['reason'],0,45,'…'))?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td class="empty" colspan="4">No activity yet.</td></tr><?php endif;?></tbody></table></div></section>
<?php elseif($page==='balances'&&in_array($me['role'],['employee','teacher','student'],true)):?><div class="heading"><div><h1>Available leave tracker</h1><div class="sub">Pending requests show projected use; approval deducts credits.</div></div><a class="btn" href="?page=leaves">Apply for leave</a></div><section class="grid" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr));margin-bottom:18px"><?php foreach($balanceSummary as $b):?><article class="card"><div class="muted"><?=e($b['category'])?></div><div class="num"><?=e(number_format($b['available'],1))?> available</div><small>Allocated <?=e(number_format($b['allocated'],1))?> · Used <?=e(number_format($b['used'],1))?></small><br><small>Pending <?=e(number_format($b['pending'],1))?> · Projected <?=e(number_format($b['projected'],1))?></small></article><?php endforeach;?></section><?php elseif($page==='admin'&&in_array($me['role'],['school_admin','personnel_officer','approving_authority'],true)):?><div class="heading"><div><h1>Admin panel</h1><div class="sub">Employee allocations, pending requests, and the credit ledger.</div></div></div><section class="card tablebox"><h2>Employee leave allocations</h2><table><thead><tr><th>Employee</th><th>Category</th><th>Used</th><th>Remaining</th><th>Set total allocation</th></tr></thead><tbody><?php foreach($adminBalances as $b):?><tr><td><?=e($b['name'])?></td><td><?=e($b['category'])?></td><td><?=e(number_format((float)$b['used_days'],1))?></td><td><?=e(number_format((float)$b['allocated_days']-(float)$b['used_days'],1))?></td><td><?php if(in_array($me['role'],['school_admin','personnel_officer'],true)):?><form method="post" class="row"><input type="hidden" name="_token" value="<?=e(token())?>"><input type="hidden" name="action" value="balance_update"><input type="hidden" name="user_id" value="<?=$b['user_id']?>"><input type="hidden" name="category" value="<?=e($b['category'])?>"><input type="number" min="0" step=".5" name="allocated_days" value="<?=e($b['allocated_days'])?>" required><button class="btn sm">Save</button></form><?php else:?><span class="muted">Personnel managed</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$adminBalances):?><tr><td class="empty" colspan="5">Add employee accounts through People to manage allocations.</td></tr><?php endif;?></tbody></table></section><section class="card tablebox" style="margin-top:18px"><h2>Pending applications</h2><table><thead><tr><th>Employee</th><th>Leave</th><th>Dates</th><th>Days</th><th>Reason</th><th>Review</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['person'])?></td><td><?=e($r['leave_type'])?></td><td><?=e($r['start_date'])?> – <?=e($r['end_date'])?></td><td><?=e($r['working_days'])?></td><td><?=e($r['reason'])?></td><td><a class="btn sm" href="?page=leaves">Review</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td class="empty" colspan="6">No pending requests.</td></tr><?php endif;?></tbody></table></section><section class="card tablebox" style="margin-top:18px"><h2>Leave credit ledger</h2><table><thead><tr><th>Date</th><th>Employee</th><th>Category</th><th>Entry</th><th>Change</th><th>Balance</th><th>Description</th></tr></thead><tbody><?php foreach($ledgerRows as $g):?><tr><td><?=e(substr($g['created_at'],0,10))?></td><td><?=e($g['person'])?></td><td><?=e($g['category'])?></td><td><?=e($g['entry_type'])?></td><td><?=e(number_format((float)$g['days_change'],1))?></td><td><?=e(number_format((float)$g['balance_after'],1))?></td><td><?=e($g['description'])?></td></tr><?php endforeach;?></tbody></table></section><?php elseif($page==='leaves'):?><div class="heading"><div><h1>Civil Service Form No. 6</h1><div class="sub">Application for Leave · Revised 2020 · UPI Elementary School</div></div><?php if(!$admin):?><button type="button" class="btn" onclick="document.getElementById('form6').scrollIntoView({behavior:'smooth'})">＋ New application</button><?php endif;?></div><?php if(!$admin):?><?php $nameParts=explode(' ',$me['name'],3);?><section class="card form printable" id="form6"><div class="section-title"><h2>Application for Leave</h2><button type="button" class="btn light small" onclick="printForm6()">Print form</button></div><details class="requirements"><summary>Instructions and requirements</summary><p>Requirements below are general guidance. Confirm the current checklist with your DepEd Division Personnel Section before filing.</p><ul><li><b>Wellness leave (CSC Resolution No. 2501292, effective January 1, 2026):</b> Permanent, temporary, substitute, coterminous, fixed-term, contractual, and casual government employees may be covered. Up to five days per calendar year, separate and exclusive from 15 Vacation Leave, 15 Sick Leave, and 3 Special Leave days. Take up to three days consecutively or on separate days. File five days ahead; for emergencies, file immediately upon return. Non-cumulative, non-commutable, and unused days are forfeited at year-end. Mental-health information is strictly confidential under the Data Privacy Act of 2012.</li><li><b>Vacation leave:</b> File five days ahead when possible; secure travel authority or clearance if traveling abroad.</li><li><b>Sick leave:</b> File immediately upon return. Attach a medical certificate when filed in advance or when absence exceeds five days, subject to Personnel requirements.</li><li><b>Maternity leave:</b> Up to 105 days; prepare proof of pregnancy and the Notice of Allocation of Maternity Leave (CS Form No. 6a) if allocating days.</li><li><b>Paternity leave:</b> Prepare the child’s birth certificate; marriage contract or medical certificate may be requested for the situation.</li><li><b>Special privilege leave:</b> Give at least one week’s notice where practicable; emergencies may be handled differently.</li><li><b>Solo parent leave:</b> Prepare a current Solo Parent ID and supporting documents requested by Personnel.</li><li><b>VAWC leave:</b> Supporting documents may include a Barangay Protection Order, temporary/permanent protection order, police report, or medical certificate.</li><li><b>Rehabilitation / special leave benefits for women:</b> Prepare medical certificates, clinical summaries, and required physician concurrence.</li><li><b>Study leave:</b> Attach program, institution, and approval documents required by the agency.</li><li><b>Emergency / calamity, adoption, and other leave:</b> Attach the applicable official order or supporting documents requested by Personnel.</li><li><b>Monetization / terminal leave:</b> Submit the separate request and clearances required by the Division Personnel and Accounting Sections.</li></ul></details><form method="post" id="civilForm6"><input type="hidden" name="_token" value="<?=e(token())?>"><input type="hidden" name="action" value="leave"><h3>1–5. Applicant information</h3><div class="form-grid"><div class="field"><label>Office / Department</label><input name="office_department" value="<?=e($me['school_name']??'UPI Elementary School')?>" required></div><div class="field"><label>Date of filing</label><input type="date" name="filing_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="field"><label>Last name</label><input name="applicant_last" value="<?=e($nameParts[2]??'')?>" required></div><div class="field"><label>First name</label><input name="applicant_first" value="<?=e($nameParts[0]??'')?>" required></div><div class="field"><label>Middle name</label><input name="applicant_middle" value="<?=e($nameParts[1]??'')?>"></div><div class="field"><label>Position</label><input name="position_title" required></div><div class="field"><label>Monthly salary (₱)</label><input type="number" min="0" step="0.01" name="salary"></div></div><h3>6.A. Type of leave to be availed of</h3><div class="leave-types"><?php $leaveTypes=['Vacation Leave'=>'Sec. 51, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Mandatory/Forced Leave'=>'Sec. 25, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Sick Leave'=>'Sec. 43, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Maternity Leave'=>'R.A. No. 11210 / IRR issued by CSC, DOLE and SSS','Paternity Leave'=>'R.A. No. 8187 / CSC MC No. 71, s. 1998, as amended','Special Privilege Leave'=>'Sec. 21, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Solo Parent Leave'=>'R.A. No. 8972 / CSC MC No. 8, s. 2004','Study Leave'=>'Sec. 68, Rule XVI, Omnibus Rules Implementing E.O. No. 292','10-Day VAWC Leave'=>'R.A. No. 9262','Rehabilitation Privilege'=>'Sec. 55, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Special Leave Benefits for Women'=>'R.A. No. 9710 / Magna Carta of Women','Special Emergency (Calamity) Leave'=>'CSC MC No. 2, s. 2012','Adoption Leave'=>'R.A. No. 8552','Wellness Leave'=>'CSC Resolution No. 2501292, effective January 1, 2026','Others'=>'Specify other leave'];foreach($leaveTypes as $lt=>$law):?><label class="leave-option"><input type="radio" name="leave_type" value="<?=e($lt)?>" required><span><b><?=e($lt)?></b><small><?=e($law)?></small></span></label><?php endforeach;?></div><h3>6.B. Details of leave</h3><div class="detail-grid"><div data-leave-detail="Vacation Leave,Special Privilege Leave"><div class="field"><label>Leave destination</label><select name="details[destination]"><option value="">Select</option><option>Within the Philippines</option><option>Abroad</option></select></div><div class="field"><label>Place / country</label><input name="details[place]" placeholder="City, province, or country"></div></div><div data-leave-detail="Sick Leave"><div class="field"><label>Medical setting</label><select name="details[medical_setting]"><option value="">Select</option><option>In hospital</option><option>Out patient</option></select></div><div class="field"><label>Illness / medical details</label><textarea name="details[illness]"></textarea></div><div class="field"><label>Hospital / clinic (if applicable)</label><input name="details[hospital]"></div></div><div data-leave-detail="Maternity Leave"><div class="field"><label>Pregnancy / childbirth details</label><textarea name="details[maternity_details]"></textarea></div><div class="field"><label>Notice of allocation (CS Form 6a), if applicable</label><select name="details[form_6a]"><option value="">Select</option><option>Attached</option><option>Not applicable</option><option>To follow</option></select></div></div><div data-leave-detail="Paternity Leave"><div class="field"><label>Spouse / child and event details</label><textarea name="details[paternity_details]"></textarea></div></div><div data-leave-detail="Solo Parent Leave"><div class="field"><label>Solo Parent ID / supporting details</label><input name="details[solo_parent_id]"></div></div><div data-leave-detail="Study Leave"><div class="field"><label>Course / degree and institution</label><textarea name="details[study_program]"></textarea></div></div><div data-leave-detail="10-Day VAWC Leave"><div class="field"><label>Case / protection order details (private)</label><textarea name="details[vawc_details]"></textarea></div></div><div data-leave-detail="Rehabilitation Privilege,Special Leave Benefits for Women"><div class="field"><label>Medical / rehabilitation details</label><textarea name="details[medical_details]"></textarea></div></div><div data-leave-detail="Special Emergency (Calamity) Leave"><div class="field"><label>Calamity and affected location</label><textarea name="details[calamity_details]"></textarea></div></div><div data-leave-detail="Adoption Leave"><div class="field"><label>Adoption / placement details</label><textarea name="details[adoption_details]"></textarea></div></div><div data-leave-detail="Wellness Leave"><div class="field"><label>Purpose</label><select name="details[wellness_purpose]"><option value="">Select wellness purpose</option><option>Mental health care</option><option>Physical wellness activities</option><option>General break from work</option></select></div><label><input type="checkbox" name="details[emergency]" value="1"> Emergency case; file immediately upon return</label><p class="muted">Mental-health information is strictly confidential. Do not include clinical details in this form.</p></div><div data-leave-detail="Others"><div class="field"><label>Specify other leave</label><input name="details[other_specification]"></div></div></div><h3>6.C–D. Dates, working days and commutation</h3><div class="form-grid"><div class="field"><label>Inclusive start date</label><input type="date" name="start" required></div><div class="field"><label>Inclusive end date</label><input type="date" name="end" required></div><div class="field"><label>Number of working days applied for</label><input type="number" min="0.5" step="0.5" name="working_days" required></div><p id="creditPreview" class="muted" data-summary="<?=e(json_encode($balanceSummary,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP))?>">Select a leave category and days to preview your balance.</p><div class="field"><label>Commutation</label><select name="commutation"><option value="not_requested">Not Requested</option><option value="requested">Requested</option></select></div></div><div class="field"><label>Purpose / additional explanation</label><textarea name="reason" required></textarea></div><div class="field"><label>Employee signature</label><input value="<?=e($me['name'])?>" readonly></div><h3>7. Details of action on application — preview</h3><div class="tablebox"><table><thead><tr><th>Leave credit certification</th><th>Vacation leave</th><th>Sick leave</th><th>Total</th></tr></thead><tbody><tr><td>Total earned</td><td>For Personnel certification</td><td>For Personnel certification</td><td>For Personnel certification</td></tr><tr><td>Less this application</td><td><?=e($_POST['working_days']??'—')?></td><td><?=e($_POST['working_days']??'—')?></td><td>—</td></tr><tr><td>Balance</td><td>To be certified</td><td>To be certified</td><td>To be certified</td></tr></tbody></table></div><div class="approval-grid"><div class="approval-box"><b>Recommendation</b><p>Allana Erica D. Cortes<br>AO IV – Personnel Section</p><span>Personnel review / signature</span></div><div class="approval-box"><b>Recommendation</b><p>Jesant Escober<br>HT-III</p><span>Recommending authority / signature</span></div><div class="approval-box"><b>Approval</b><p>Cheryll V. Bermudo<br>Assistant Schools Division Superintendent</p><span>Approving authority / signature</span></div></div><div class="actions no-print"><button class="btn" type="submit">Submit Form No. 6</button><button class="btn light" type="button" onclick="printForm6()">Print form</button></div></form></section><?php endif;?><section class="card tablebox"><h2>Submitted applications</h2><table><thead><tr><th>Applicant</th><th>Leave type</th><th>Dates / days</th><th>Reason</th><th>Status</th><?php if($admin):?><th>Review</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(trim(($r['applicant_last']??'').' '.($r['applicant_first']??'').' '.($r['applicant_middle']??''))?:$r['person'])?><br><small><?=e($r['role'])?></small></td><td><?=e($r['leave_type']??'Leave')?></td><td><?=e($r['start_date'])?> – <?=e($r['end_date'])?><br><small><?=e($r['working_days']??'—')?> working days</small></td><td><?=e($r['reason'])?><?php if(!empty($r['details_json'])):?><details><summary>Form details</summary><pre><?=e($r['details_json'])?></pre></details><?php endif;?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><?php if($admin):?><td><?php if(in_array($me['role'],['school_admin','personnel_officer'],true)):?><details><summary>Personnel review</summary><form method="post" class="review-form"><input type="hidden" name="_token" value="<?=e(token())?>"><input type="hidden" name="action" value="hr_review"><input type="hidden" name="id" value="<?=$r['id']?>"><label>VL earned <input type="number" step=".01" min="0" name="vl_earned" value="<?=e($r['vl_earned']??'')?>"></label><label>VL less <input type="number" step=".01" min="0" name="vl_less" value="<?=e($r['vl_less']??'')?>"></label><label>SL earned <input type="number" step=".01" min="0" name="sl_earned" value="<?=e($r['sl_earned']??'')?>"></label><label>SL less <input type="number" step=".01" min="0" name="sl_less" value="<?=e($r['sl_less']??'')?>"></label><textarea name="personnel_remarks" placeholder="Personnel certification remarks"><?=e($r['personnel_remarks']??'')?></textarea><select name="recommendation"><option value="">Recommendation…</option><option value="approval" <?=$r['recommendation']==='approval'?'selected':''?>>Approval</option><option value="disapproval" <?=$r['recommendation']==='disapproval'?'selected':''?>>Disapproval</option></select><button class="btn sm">Save certification</button></form></details><?php endif;?><?php if(in_array($me['role'],['school_admin','personnel_officer','approving_authority','platform_admin'],true)):?><details><summary>Authority decision</summary><form method="post" class="review-form"><input type="hidden" name="_token" value="<?=e(token())?>"><input type="hidden" name="action" value="authority_decision"><input type="hidden" name="id" value="<?=$r['id']?>"><label>Approved days with pay<input type="number" min="0" step=".5" name="days_with_pay" value="<?=e($r['approval_days_with_pay']??'')?>"></label><label>Days without pay<input type="number" min="0" step=".5" name="days_without_pay" value="<?=e($r['approval_days_without_pay']??'')?>"></label><textarea name="authority_remarks" placeholder="Decision remarks"><?=e($r['authority_remarks']??'')?></textarea><button class="btn sm" name="status" value="approved">Approve</button><button class="btn light sm" name="status" value="rejected">Disapprove</button></form></details><?php endif;?></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td class="empty" colspan="6">No applications yet.</td></tr><?php endif;?></tbody></table></section>
<?php elseif($page==='attendance'):?><?php $byDate=[];$totals=['present'=>0,'absent'=>0,'leave'=>0,'holiday'=>0];foreach($rows as $record){$byDate[$record['attendance_date']]=$record;$totals[$record['status']]++;}$monthName=$first->format('F Y');$prevMonth=$first->modify('-1 month')->format('Y-m');$nextMonth=$first->modify('+1 month')->format('Y-m');$today=date('Y-m-d');?><div class="heading"><div><h1>Monthly attendance / DTR</h1><div class="sub">Daily time record · Philippines time (Asia/Manila) · <?=e($me['name'])?></div></div><div class="row"><a class="btn light sm" href="?page=attendance&amp;month=<?=e($prevMonth)?>">← Previous</a><strong><?=e($monthName)?></strong><?php if($nextMonth<=date('Y-m')):?><a class="btn light sm" href="?page=attendance&amp;month=<?=e($nextMonth)?>">Next →</a><?php endif;?></div></div><section class="grid"><article class="card"><div class="stat">Days present</div><div class="num"><?=$totals['present']?></div></article><article class="card"><div class="stat">Days absent</div><div class="num"><?=$totals['absent']?></div></article><article class="card"><div class="stat">Leave</div><div class="num"><?=$totals['leave']?></div></article><article class="card"><div class="stat">Holidays</div><div class="num"><?=$totals['holiday']?></div></article></section><section class="card form section"><h2>Record or update a day</h2><form method="post" class="row" style="flex-wrap:wrap"><input type="hidden" name="_token" value="<?=e(token())?>"><input type="hidden" name="action" value="attendance"><input type="hidden" name="month" value="<?=e($first->format('Y-m'))?>"><label>Date <input type="date" name="attendance_date" min="<?=e($first->format('Y-m-d'))?>" max="<?=e($first->format('Y-m')===date('Y-m')?min($today,$last->format('Y-m-d')):$last->format('Y-m-d'))?>" value="<?=e($first->format('Y-m')===date('Y-m')?$today:$first->format('Y-m-d'))?>" required></label><label>Status <select name="status"><option value="present">Present</option><option value="absent">Absent</option><option value="leave">Leave</option><option value="holiday">Holiday</option></select></label><label>Time in <input type="time" name="time_in"></label><label>Time out <input type="time" name="time_out"></label><button class="btn">Save DTR</button></form></section><section class="card section tablebox"><table><thead><tr><th>Date</th><th>Day</th><th>Time in</th><th>Time out</th><th>Total hours</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php for($day=$first;$day<=$last;$day=$day->modify('+1 day')):$key=$day->format('Y-m-d');$rec=$byDate[$key]??null;$hours='—';if($rec&&$rec['time_in']&&$rec['time_out']){$minutes=(strtotime($rec['time_out'])-strtotime($rec['time_in']))/60;if($minutes>=0)$hours=number_format($minutes/60,2).' h';}?><tr><td><?=e($day->format('M j, Y'))?></td><td><?=e($day->format('l'))?></td><td><?=e($rec['time_in']?substr($rec['time_in'],0,5):'—')?></td><td><?=e($rec['time_out']?substr($rec['time_out'],0,5):'—')?></td><td><?=e($hours)?></td><td><?php if($rec):?><span class="badge <?=e($rec['status'])?>"><?=e(ucfirst($rec['status']))?></span><?php else:?><span class="badge">Not recorded</span><?php endif;?></td><td><?=e($rec['remarks']??'')?></td></tr><?php endfor;?></tbody></table></section>
